/* Stack: visible collapse → open, and the same page grammar for every Part and Tool. */
const app=document.querySelector('#app'),trail=document.querySelector('#trail'),live=document.querySelector('#announcement');
let path=['phone','speaker'],uid=0,navBusy=false;
const state=new Map(),nodes={};
const add=(id,title,type='Part',description='',input=false)=>nodes[id]={title,type,description,input,icon:type==='Tool'?'⌑':'◉',sample:id!=='speaker'};
add('phone','Phone','Part','A system of parts, including the speaker');
add('speaker','Speaker','Part','A small machine that moves air');
add('coil','Copper voice coil','Part','A wire loop that moves with the membrane');
add('wire','Insulated wire','Part','A conducting core with an insulating skin');
add('fixture','Winding fixture','Tool','A removable form and a wire guide');
add('alignment','Alignment fixture','Tool','A locating nest and centering gauges');
add('magnet','Permanent magnet','Part','A body with a persistent magnetic field');
add('iron','Iron flux parts','Part','Pole and return surfaces guide the field');
add('membrane','Diaphragm + surround','Part','A thin film with a compliant edge');
add('frame','Speaker frame','Part','A structure that holds the assembly');
add('enclosure','Rear enclosure','Part','The acoustic space behind the membrane');
add('adhesive','Adhesive','Part','Joins parts and seals the surround',true);
add('leads','Terminals + flexible leads','Part','The electrical connection to the coil');
add('meter','Meter','Tool','Measures continuity and electrical resistance');
add('signal','Audio signal source','Tool','Produces the changing test signal');
add('amplifier','Audio amplifier','Tool','Drives the speaker with the test signal');
add('microphone','Measurement microphone','Tool','Captures sound for response checks');
add('power','Power source','Tool','Converts supplied energy into electrical output');
add('clamp','Assembly clamp','Tool','Holds fixed parts as their joints are made');
add('mandrel','Shaped mandrel','Part','The removable forming part of a winding fixture');
add('guide','Wire guide','Part','A guiding part of the winding fixture');
add('coating','Insulating coating','Part','Separates neighboring turns electrically',true);
add('stock','Metal stock','Part','The starting shape for machined parts',true);
add('base','Metal base','Part','Supports the working parts of a tool');
add('bearings','Bearings','Part','Support a shaft while allowing rotation');
add('gauges','Centering gauges','Part','Set the position of a moving assembly');
add('fasteners','Fasteners','Part','Join tool parts while allowing disassembly');
add('shaft','Shaft','Part','Carries rotation between the drive and rotor');
add('winding','Generator winding','Part','A winding formed from insulated wire');
add('board','Circuit board','Part','Supports and connects a tool’s circuitry');
add('display','Display','Part','Shows the meter’s measured result');
add('resistors','Reference resistors','Part','Known electrical values for a measuring circuit');
add('capsule','Microphone capsule','Part','Converts sound into an electrical signal');
add('case','Enclosure + connectors','Part','Protects and connects an electrical tool');
add('conditioning','Output-conditioning circuit','Part','Rectifies or regulates generator output');
add('alloy','Magnetic material','Part','The chosen magnetic starting material',true);
add('ironstock','Iron stock','Part','The starting material for flux parts',true);
add('lathe','Lathe','Tool','Shapes a rotating workpiece');
add('drill','Drill press','Tool','Forms controlled holes in tool parts');
add('mill','Milling machine','Tool','Shapes flat and locating surfaces');
add('driver','Fastening driver','Tool','Fits fasteners while assembling a tool');
add('caliper','Caliper','Tool','Checks tool-part dimensions');
add('solder','Soldering iron','Tool','Joins electrical connections');
add('press','Forming press','Tool','Forms a magnetic body');
add('furnace','Furnace','Tool','Provides controlled process heating');
add('grinder','Finishing grinder','Tool','Finishes working surfaces');
add('magnetizer','Magnetizer','Tool','Applies the field used to magnetize a body');
add('drive','Mechanical drive','Tool','Supplies mechanical input to a generator');
function getUI(id){if(!state.has(id))state.set(id,{open:id==='speaker'?['speaker-2']:[],scroll:0,selected:'all',motion:true,focusStep:null,focusChild:null});return state.get(id)}
function saveCurrent(){const ui=getUI(path.at(-1));ui.scroll=window.scrollY;ui.open=[...app.querySelectorAll('.step details[open]')].map(d=>d.id)}
function relation(id,index=path.indexOf(id)){if(index<1)return 'The whole device';const parent=nodes[path[index-1]].title;return nodes[id].type==='Tool'?`used to make ${parent}`:nodes[id].input?`input to making ${parent}`:`part of ${parent}`}
function announce(text){live.textContent=text}
function compactHeader(id,index,fold=false){const n=nodes[id];return `<button class="ancestor-button ${fold?'fold-header':''}" ${fold?'tabindex="-1"':`data-ancestor="${index}"`} aria-label="Return to ${n.title}"><span class="ancestor-mini ${n.type==='Tool'?'tool':''}" aria-hidden="true">${n.icon}</span><span><span class="ancestor-title">${n.title}</span><span class="ancestor-sub">${n.type}${index?' · '+relation(id,index):''}</span></span><span class="ancestor-description">${n.description}</span><span class="ancestor-open">Open this level <span aria-hidden="true">↗</span></span></button>`}
const ease=t=>1-Math.pow(1-t,3),reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
async function animateHeight(card,from,to,duration,scrollTarget){if(reduced())duration=1;const startScroll=window.scrollY,start=performance.now();card.style.height=from+'px';card.style.overflow='hidden';const animation=card.animate([{height:from+'px'},{height:to+'px'}],{duration,easing:'cubic-bezier(.22,.65,.24,1)',fill:'forwards'});const track=now=>{const t=Math.min(1,(now-start)/duration);if(scrollTarget!==undefined)window.scrollTo({top:startScroll+(scrollTarget-startScroll)*ease(t),behavior:'instant'});if(t<1)requestAnimationFrame(track)};requestAnimationFrame(track);await animation.finished;card.style.height=to+'px';animation.cancel()}
async function foldCurrent(close=false){const id=path.at(-1),card=app.querySelector('.active-card'),height=card.getBoundingClientRect().height;const top=card.getBoundingClientRect().top+window.scrollY;card.insertAdjacentHTML('afterbegin',compactHeader(id,path.length-1,true));card.classList.add('is-folding');await animateHeight(card,height,close?0:78,780,Math.max(0,top-100))}
async function unfoldCurrent(returning=false){const id=path.at(-1),card=app.querySelector('.active-card'),height=card.getBoundingClientRect().height;card.classList.add('is-opening');card.insertAdjacentHTML('afterbegin',compactHeader(id,path.length-1,true));await animateHeight(card,returning?78:0,height,720);card.classList.remove('is-opening');card.querySelector('.fold-header').remove();card.style.height='';card.style.overflow='';const heading=card.querySelector('h1');heading.setAttribute('tabindex','-1');heading.focus({preventScroll:true});trail.scrollLeft=trail.scrollWidth}
async function route(id,button){if(navBusy)return;if(path.includes(id))return restore(path.indexOf(id));saveCurrent();const ui=getUI(path.at(-1));ui.focusChild=id;ui.focusStep=button?.closest('.step')?.dataset.step;navBusy=true;app.setAttribute('aria-busy','true');await foldCurrent();path.push(id);getUI(id);render();await unfoldCurrent();navBusy=false;app.removeAttribute('aria-busy');announce(`Opened ${nodes[id].title}. The previous card has collapsed above it.`)}
async function restore(index){if(navBusy||index===path.length-1)return;saveCurrent();navBusy=true;app.setAttribute('aria-busy','true');await foldCurrent(true);path=path.slice(0,index+1);render();await unfoldCurrent(true);const ui=getUI(path.at(-1));window.scrollTo({top:ui.scroll,behavior:reduced()?'instant':'smooth'});const scope=ui.focusStep?app.querySelector(`[data-step="${ui.focusStep}"]`):app;const button=scope?.querySelector(`[data-go="${ui.focusChild}"]`);button?.focus({preventScroll:true});navBusy=false;app.removeAttribute('aria-busy');announce(`Returned to ${nodes[path.at(-1)].title}. The saved step and focus are restored.`)}
function chip(id,label=nodes[id].title,demo=false){const n=nodes[id];return `<button class="part-chip ${n.type==='Tool'?'tool':''} ${demo?'try':''}" data-go="${id}" title="${n.type} · Open how it is made" aria-label="${label}. ${n.type}. Open how it is made"><span class="role-dot" aria-hidden="true"></span>${label}<small class="mini-role">${n.type.toLowerCase()}</small><span class="arrow" aria-hidden="true">↘</span></button>`}
const S=(id,kind,title,summary,detail,tools=[],use='')=>({id,kind,title,summary,detail,tools,use});

function svgDefs(){const id='a'+(++uid);return {id,markup:`<defs><linearGradient id="${id}-metal" x1="0" y1="0" x2=".85" y2="1"><stop stop-color="#f7f5ea"/><stop offset=".38" stop-color="#b7c3bd"/><stop offset=".66" stop-color="#e4e7dd"/><stop offset="1" stop-color="#81938f"/></linearGradient><linearGradient id="${id}-film" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#ecffff"/><stop offset=".4" stop-color="#9bdbd6"/><stop offset=".7" stop-color="#d0f2eb"/><stop offset="1" stop-color="#67b7b3"/></linearGradient><linearGradient id="${id}-copper" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#f9cc8c"/><stop offset=".26" stop-color="#db8b48"/><stop offset=".55" stop-color="#f5bc77"/><stop offset="1" stop-color="#aa532f"/></linearGradient><linearGradient id="${id}-blue" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#d8cf9c"/><stop offset=".5" stop-color="#b4a56a"/><stop offset="1" stop-color="#8d7b45"/></linearGradient><filter id="${id}-shadow" x="-30%" y="-30%" width="160%" height="180%"><feDropShadow dx="1" dy="9" stdDeviation="6" flood-color="#3a5045" flood-opacity=".12"/></filter><pattern id="${id}-hatch" width="5" height="5" patternUnits="userSpaceOnUse"><path d="M0 5 5 0" stroke="#637a70" stroke-width=".4" opacity=".18"/></pattern></defs>`}}
function coilRing(id,extra=''){return `<g ${extra}><rect x="31" y="30" width="242" height="93" rx="39" fill="none" stroke="url(#${id}-copper)" stroke-width="17"/>${Array.from({length:7},(_,i)=>`<rect x="${25+i*1.5}" y="${24+i*1.3}" width="${254-i*3}" height="${105-i*2.6}" rx="${43-i}" fill="none" stroke="${i%2?'#f8ce92':'#a6532d'}" stroke-width="1" opacity=".9"/>`).join('')}<path d="M36 113 8 134-24 134M269 108 293 119 321 119" fill="none" stroke="#b86637" stroke-width="4"/><path d="M36 112 8 133-24 133M269 107 293 118 321 118" fill="none" stroke="#f0b47e" stroke-width="1"/></g>`}
function exploded(selected='all'){
 const {id,markup}=svgDefs();const cls=p=>`layer ${selected!=='all'&&selected!==p?'dim':''}`;
 const spot=(n,x,y,p)=>`<g class="hotspot ${selected===p?'selected':''}" data-select="${p}" role="button" tabindex="0" aria-label="Highlight ${['','diaphragm and surround','copper voice coil','magnetic system','frame and rear enclosure'][n]}"><circle cx="${x}" cy="${y}" r="34" fill="transparent"/><circle class="number" cx="${x}" cy="${y}" r="15" fill="#fff" stroke="#4a756c" stroke-width="1"/><text x="${x}" y="${y+4}" text-anchor="middle" fill="#315d54" font-size="11">${n}</text></g>`;
 return `<svg viewBox="0 0 520 425" role="group" aria-label="Exploded technical view: diaphragm, copper coil, magnetic system and frame. Select a numbered layer.">${markup}<ellipse cx="259" cy="368" rx="145" ry="16" fill="#cdd8cf" opacity=".22"/><path d="M253 81v245" stroke="#99b5a6" stroke-dasharray="4 5" opacity=".6"/><g class="${cls('frame')}" filter="url(#${id}-shadow)" transform="matrix(.98,-.24,.42,.65,80,293)"><path d="M0 34Q0 3 32 3h245q31 0 31 31v112q0 31-31 31H32Q0 177 0 146Z M24 42v97q0 12 12 12h237q12 0 12-12V42q0-14-14-14H38q-14 0-14 14Z" fill="url(#${id}-metal)" fill-rule="evenodd" stroke="#778a82" stroke-width="1.4"/><path d="M0 145v18q0 30 32 30h245q31 0 31-30v-19q0 32-31 32H32q-32 0-32-31Z" fill="#96a59c" stroke="#6e8178" stroke-width="1"/><rect x="9" y="7" width="290" height="161" rx="27" fill="none" stroke="#f9fff6" opacity=".8"/><path d="M51 31h198v117H51Z" fill="url(#${id}-hatch)" opacity=".18"/>${[[16,23],[290,23],[16,157],[290,157]].map(([x,y])=>`<ellipse cx="${x}" cy="${y}" rx="5" ry="4" fill="#687b73"/><ellipse cx="${x}" cy="${y-1}" rx="3" ry="2" fill="#bbc8bd"/>`).join('')}</g>
 <g class="${cls('magnet')}" filter="url(#${id}-shadow)" transform="matrix(.98,-.24,.42,.65,80,211)"><rect x="4" y="13" width="300" height="142" rx="25" fill="#8f9f99" stroke="#74877e"/><path d="M4 136v15q0 25 25 25h250q25 0 25-25v-17q0 24-25 24H29q-25 0-25-22Z" fill="#71847c"/><rect x="11" y="20" width="286" height="126" rx="20" fill="url(#${id}-metal)" stroke="#73857d"/><rect x="25" y="30" width="54" height="107" rx="10" fill="url(#${id}-blue)" stroke="#456085"/><rect x="231" y="30" width="54" height="107" rx="10" fill="url(#${id}-blue)" stroke="#456085"/><rect x="91" y="34" width="129" height="102" rx="12" fill="#778980"/><rect x="91" y="25" width="129" height="102" rx="12" fill="url(#${id}-metal)" stroke="#6e857b"/><rect x="95" y="29" width="121" height="94" rx="9" fill="url(#${id}-hatch)"/><ellipse cx="155" cy="76" rx="10" ry="8" fill="#70857b"/><ellipse cx="155" cy="74" rx="7" ry="5" fill="#a4b0a4"/><path d="M83 36v96M226 36v96" stroke="#35594c" stroke-width="3"/><path d="M29 33h44M235 33h44M95 30h114" stroke="#d9e6df" stroke-width="1" opacity=".8"/></g>
 <g class="${cls('coil')}" filter="url(#${id}-shadow)" transform="matrix(.98,-.24,.42,.65,80,142)">${coilRing(id)}</g>
 <g class="${cls('membrane')}" filter="url(#${id}-shadow)" transform="matrix(.98,-.24,.42,.65,80,62)"><rect x="0" y="1" width="309" height="151" rx="37" fill="url(#${id}-film)" stroke="#4b9d98" stroke-width="1.2"/><rect x="6" y="7" width="297" height="138" rx="32" fill="none" stroke="#e6ffff" stroke-width="2"/><rect x="17" y="18" width="275" height="116" rx="39" fill="none" stroke="#62aaa6" stroke-width="1"/><rect x="23" y="23" width="263" height="106" rx="36" fill="none" stroke="#ebffff" stroke-width="2"/><rect x="45" y="36" width="218" height="80" rx="33" fill="url(#${id}-film)" stroke="#65b3ae"/><rect x="52" y="42" width="204" height="66" rx="28" fill="#e6fbf5" opacity=".5"/>${Array.from({length:13},(_,i)=>`<path d="M${44+i*17} 20q-4 8 2 17M${44+i*17} 116q-4 8 2 17" fill="none" stroke="#69b3ae" stroke-width=".8"/><path d="M${47+i*17} 20q-4 8 2 17M${47+i*17} 116q-4 8 2 17" fill="none" stroke="#f2ffff" stroke-width="1"/>`).join('')}<path d="M25 36 43 48M18 49 40 58M17 66 43 69M22 87 44 83M283 39 264 50M291 54 269 62M291 73 270 73M286 96 265 87" stroke="#6eb6b0" stroke-width="1" fill="none"/></g>
 <g fill="none" stroke="#8ba89b" stroke-width="1"><path d="M82 93 113 93"/><path d="M394 158 430 160"/><path d="M87 262 111 262"/><path d="M386 334 424 335"/></g>${spot(1,67,93,'membrane')}${spot(2,445,160,'coil')}${spot(3,72,262,'magnet')}${spot(4,439,335,'frame')}<text x="285" y="399" text-anchor="middle" font-size="10" letter-spacing="1.5" fill="#8b9991">EXPLODED VIEW · NOT TO SCALE</text></svg>`
}
function crossSection(){return `<svg viewBox="0 0 420 180" role="img" aria-label="Cross-section: diaphragm and copper coil move together; the magnet and frame stay still."><g stroke="#365b55" stroke-width="1.5"><path d="M61 94v56h278V94h-25v40H88V94Z" fill="#dce4d9"/><path d="M124 119h149v15H124Z" fill="#becac0"/><rect x="175" y="111" width="51" height="23" rx="2" fill="#b4a56a"/><path d="M87 94h34v32H87ZM278 94h36v32h-36Z" fill="#b6c4b6"/></g><g class="moving"><path d="M42 73q12-15 23-1t22 0l44-15h135l43 15q13 14 25 0t23 1" fill="none" stroke="#369f94" stroke-width="4" stroke-linecap="round"/><path d="M130 58v58M273 59v57" fill="none" stroke="#a45938" stroke-width="5"/>${Array.from({length:7},(_,i)=>`<path d="M125 ${71+i*6}h10M268 ${71+i*6}h10" stroke="#e8a567" stroke-width="3"/>`).join('')}</g><path d="M205 20v24m-4-6 4 6 4-6" fill="none" stroke="#369f94" stroke-width="1.5"/><text x="204" y="13" text-anchor="middle" font-size="11" fill="#2e7d70">membrane + coil move</text><path d="M205 171v-26m-4 6 4-6 4 6" fill="none" stroke="#6d7fab" stroke-width="1.5"/><text x="257" y="172" font-size="10" fill="#64769b">magnet stays still</text><g fill="none" stroke="#65a496" stroke-width="1.4"><path class="wave" d="M365 70q15 15 0 31"/><path class="wave" d="M374 61q24 24 0 48"/><path class="wave" d="M384 51q33 34 0 67"/></g></svg>`}
function stepDiagram(kind){const {id,markup}=svgDefs();let drawing='';
 const fixed=`<path d="M32 57v47h139V57h-16v32H47V57Z" fill="#dbe3d7" stroke="#456056"/><rect x="79" y="72" width="45" height="17" rx="2" fill="url(#${id}-blue)" stroke="#58729b"/><rect x="62" y="64" width="79" height="9" rx="2" fill="url(#${id}-metal)" stroke="#7e9485"/>`;
 const moving=`<path d="M25 49q8-9 16 0t17 0l24-9h47l25 9q9 9 17 0t16 0" fill="none" stroke="#5aaca0" stroke-width="2.5"/><path d="M66 43v34M140 43v34" stroke="#b66a39" stroke-width="4"/>${[49,56,63,70].map(y=>`<path d="M62 ${y}h8M136 ${y}h8" stroke="#e5ab69" stroke-width="2"/>`).join('')}`;
 if(kind==='magnet')drawing=`${fixed}<path d="M51 68h9m-4-3 4 3-4 3M151 68h-8m4-3-4 3 4 3" stroke="#51a899" fill="none"/><text x="101" y="43" text-anchor="middle" font-size="10" fill="#719082">fixed magnetic gap</text><path d="M101 48v11" stroke="#719082" stroke-dasharray="2 2"/>`;
 if(kind==='join')drawing=`<g transform="translate(29,4) scale(.47,.38)">${coilRing(id)}</g><path d="M101 57v12m-4-5 4 5 4-5" stroke="#bd7f50" fill="none"/><ellipse cx="101" cy="86" rx="75" ry="15" fill="url(#${id}-film)" stroke="#61a298"/><ellipse cx="101" cy="83" rx="61" ry="8" fill="none" stroke="#93c8ba"/><path d="m163 51-18 28m7-37 14 8-4 6-14-7Z" fill="#d3dbeb" stroke="#7e8dad"/>`;
 if(kind==='center')drawing=`${fixed}${moving}<path d="M101 13v18m-4-5 4 5 4-5" stroke="#59a296" fill="none"/><path d="M24 29 46 51m-5-9 5 9-9-4M182 29l-22 22m4-9-4 9 9-4" stroke="#91a2c0" fill="none" stroke-dasharray="3 2"/>`;
 if(kind==='test')drawing=`<g transform="translate(35,8) scale(.64)">${fixed}${moving}</g><rect x="8" y="58" width="31" height="39" rx="4" fill="#f1eadb" stroke="#a59674"/><rect x="13" y="64" width="21" height="12" rx="1" fill="#dae9d9"/><text x="24" y="72" text-anchor="middle" font-size="6" fill="#5b7861">Ω</text><circle cx="24" cy="85" r="5" fill="#d0c7af" stroke="#a59674"/><path d="M28 96h45V82M18 96v7h84V81" fill="none" stroke="#bf865b"/><path d="M157 46q17 17 0 35m9-43q25 25 0 50" fill="none" stroke="#67b1a3" stroke-width="1.4"/><path d="M181 63v14q0 5 5 5t5-5V63q0-5-5-5t-5 5Z" fill="#e1e5ef" stroke="#8693b2"/><path d="M176 72v8q0 10 10 10t10-10v-8M186 90v10m-6 0h12" fill="none" stroke="#8693b2"/>`;
 if(kind==='wire')drawing=`<path d="M28 84q23-64 60-30t45 11q30-19 49-3" fill="none" stroke="#b87042" stroke-width="7"/><path d="M28 84q23-64 60-30t45 11q30-19 49-3" fill="none" stroke="#e4a26f" stroke-width="3"/><circle cx="35" cy="45" r="15" fill="#f5c18a" stroke="#a6673c"/><circle cx="35" cy="45" r="10" fill="#d28a52" stroke="#a6673c"/><path d="M51 42h39" stroke="#b6c0ad" stroke-dasharray="2 3"/><text x="91" y="43" font-size="9" fill="#8e7958">thin insulation</text>`;
 if(kind==='wind')drawing=`<rect x="50" y="51" width="104" height="33" rx="14" fill="url(#${id}-metal)" stroke="#7e9287"/><g transform="translate(32,27) scale(.46,.43)">${coilRing(id)}</g><path d="M63 35q39-22 78 1m-5-7 5 7-8 2" fill="none" stroke="#719a86"/><path d="M155 66h26" stroke="#b87042" stroke-width="3"/>`;
 if(kind==='release')drawing=`<g transform="translate(25,29) scale(.49,.4)">${coilRing(id)}</g><rect x="58" y="66" width="110" height="27" rx="12" fill="url(#${id}-metal)" stroke="#7e9287"/><path d="M103 100v10m-4-6 4 6 4-6" stroke="#719a86" fill="none"/><path d="M44 48v-16m-4 5 4-5 4 5" stroke="#b7875b" fill="none"/>`;
 if(kind==='fixture')drawing=`<path d="m40 91 18-10h106l20 10-20 13H58Z" fill="#d9e0d2" stroke="#81947f"/><path d="M40 91v10l18 13h106l20-13V91l-20 13H58Z" fill="#b5c2af" stroke="#81947f"/><rect x="65" y="51" width="98" height="28" rx="10" fill="url(#${id}-metal)" stroke="#7b9183"/><path d="M94 79v11M137 79v11" stroke="#81947f" stroke-width="8"/><path d="M45 86V39h15M158 38h18v46" stroke="#899ab7" stroke-width="4" fill="none"/><path d="M176 43 145 56" stroke="#bb8556" stroke-width="2"/>`;
 if(kind==='guide')drawing=`<rect x="32" y="88" width="142" height="15" rx="4" fill="#d2ddd0" stroke="#81947f"/><path d="M58 89V43h24" fill="none" stroke="#8395b5" stroke-width="6"/><circle cx="87" cy="43" r="9" fill="#edf0f7" stroke="#8191ad"/><circle cx="87" cy="43" r="3" fill="#bac8da"/><path d="M87 42q28-19 53 8t36-10" fill="none" stroke="#c78851" stroke-width="3"/><path d="M107 39h21m-6-4 6 4-6 4" fill="none" stroke="#759785"/>`;
 if(kind==='coat')drawing=`<rect x="26" y="50" width="150" height="26" rx="13" fill="#ebcfac" stroke="#a3825a"/><rect x="26" y="55" width="150" height="16" rx="8" fill="url(#${id}-copper)"/><path d="M113 35v12m-4-5 4 5 4-5" stroke="#a3825a" fill="none"/><text x="101" y="25" font-size="9" text-anchor="middle" fill="#967c57">coat around conductor</text>`;
 return `<svg viewBox="0 0 205 122" role="img" aria-label="${kind} concept illustration">${markup}${drawing}</svg>`;
}

function sampleArt(id){const d=svgDefs();if(id==='coil')return `<svg viewBox="0 0 460 310" role="img" aria-label="A copper voice coil on a removable winding form">${d.markup}<ellipse cx="242" cy="256" rx="144" ry="16" fill="#e7e9dc"/><g transform="matrix(1,-.2,.35,.7,44,150)" filter="url(#${d.id}-shadow)"><rect x="24" y="28" width="257" height="112" rx="44" fill="url(#${d.id}-metal)" stroke="#8c9d8e"/><rect x="29" y="19" width="247" height="112" rx="42" fill="#e4e8dc" stroke="#91a590"/><rect x="37" y="25" width="232" height="94" rx="36" fill="url(#${d.id}-hatch)"/></g><g transform="matrix(1,-.2,.35,.7,44,103)" filter="url(#${d.id}-shadow)">${coilRing(d.id)}</g><path d="M82 70h62v28" fill="none" stroke="#b08b61"/><text x="55" y="56" fill="#a4744f" font-size="12">the part you keep</text><path d="M355 204h-33v-30" fill="none" stroke="#8aa18b"/><text x="345" y="222" fill="#728d76" font-size="11" text-anchor="middle">the form comes out</text><path d="M251 89v23m-5-8 5 8 5-8" fill="none" stroke="#92b199" stroke-dasharray="3 3"/></svg>`;
 if(id==='fixture')return `<svg viewBox="0 0 440 305" role="img" aria-label="Winding fixture with removable mandrel and wire guide">${d.markup}<ellipse cx="233" cy="267" rx="136" ry="13" fill="#dfe6dc"/><g filter="url(#${d.id}-shadow)"><path d="m74 220 32-18h220l40 18-36 25H111Z" fill="#dce5d5" stroke="#92a78e"/><path d="M74 220v16l37 25h219l36-25v-16l-36 25H111Z" fill="#a9bca1" stroke="#829d7d"/><path d="M175 166v41M267 163v42" stroke="#9cafa0" stroke-width="18"/><g transform="matrix(.85,-.15,.3,.6,94,110)"><rect x="30" y="26" width="240" height="105" rx="36" fill="url(#${d.id}-metal)" stroke="#7f9784"/>${coilRing(d.id)}</g><path d="M94 215V80h24M327 209V82h-38" fill="none" stroke="#8799b8" stroke-width="9" stroke-linejoin="round"/><circle cx="279" cy="82" r="14" fill="#e7eaf1" stroke="#7285a9" stroke-width="2"/><circle cx="279" cy="82" r="5" fill="#7285a9"/><path d="M342 44q-23 4-64 38l-53 46" fill="none" stroke="#c28c54" stroke-width="3"/></g><path d="M48 100h40" fill="none" stroke="#85988f"/><text x="46" y="88" fill="#7b9186" font-size="11">wire guide</text><path d="M352 152h-32" fill="none" stroke="#85988f"/><text x="353" y="141" fill="#7b9186" font-size="11" text-anchor="middle">removable form</text></svg>`;
 return `<svg viewBox="0 0 440 300" role="img" aria-label="Insulated copper wire enlarged to show its conductor and insulating outer layer">${d.markup}<path d="M52 210q45-142 154-69t104 18q32-47 83-14" fill="none" stroke="#b58c5c" stroke-width="18"/><path d="M52 210q45-142 154-69t104 18q32-47 83-14" fill="none" stroke="#ecc18a" stroke-width="13"/><path d="M52 210q45-142 154-69t104 18q32-47 83-14" fill="none" stroke="#dba46b" stroke-width="7"/><circle cx="96" cy="74" r="38" fill="#ebcf9f" stroke="#a28761" stroke-width="2"/><circle cx="96" cy="74" r="29" fill="url(#${d.id}-copper)" stroke="#a96b3d"/><path d="M136 58h55M128 78h57" fill="none" stroke="#ab9675"/><text x="198" y="62" font-size="12" fill="#9a8158">insulation</text><text x="193" y="82" font-size="12" fill="#a3673f">copper core</text><text x="226" y="267" text-anchor="middle" font-size="10" letter-spacing="1" fill="#97a190">ENLARGED MATERIAL VIEW</text></svg>`}

const speakerSteps=[
 S('speaker-1','magnet','Build the fixed magnetic system','Make a field across the air gap, with a solid structure around it.',()=>`Seat the ${chip('magnet')} against the ${chip('iron')}: the pole and return surfaces guide the magnetic field across a narrow gap. Join these fixed parts to the ${chip('frame')} and ${chip('enclosure')}. The ${chip('clamp')} holds the parts still while ${chip('adhesive')} joins their locating faces. The magnet, iron and frame stay fixed when the speaker plays.`,['clamp'],'The clamp holds the fixed magnetic parts against their locating surfaces while the joint is made.'),
 S('speaker-2','join','Join the coil and membrane','Wind a light wire loop, then attach it to the film that will move the air.',()=>`Form the ${chip('coil','Copper voice coil',true)} with a ${chip('fixture','Winding fixture',true)}. Its removable mandrel defines the loop; its wire guide places the turns. Release the finished coil, then use ${chip('adhesive')} to join it to the ${chip('membrane')}. The coil and film now move as one assembly. Leave the coil’s leads free to reach the terminals.`,['fixture'],'The winding fixture holds the loop’s shape while the guide places the turns. The mandrel is removed; the copper coil stays.'),
 S('speaker-3','center','Center and seal the moving assembly','Locate the coil in the gap and give it room to move without rubbing.',()=>`The ${chip('alignment','Alignment fixture',true)} locates the moving assembly against the ${chip('iron')}. Its centering gauges hold the coil away from the gap walls. Bond the surround to the ${chip('frame')}, sealing its edge with ${chip('adhesive')}. Remove the gauges once the joint is stable. The membrane must move freely; neither the fixture nor its gauges stays in the finished speaker.`,['alignment'],'The alignment fixture approaches the moving assembly, holds the coil centered in the gap, then withdraws after the joint is stable.'),
 S('speaker-4','test','Connect and test','Check the electrical path, mechanical clearance and acoustic response.',()=>`Connect the ${chip('leads')} to the coil. First use a ${chip('meter')} to check continuity and DC resistance. For the acoustic check, the ${chip('signal')} feeds the ${chip('amplifier')}, which supplies a controlled changing current to the speaker. A ${chip('power')} runs the powered test devices. The ${chip('microphone')} captures the sound so response and rub-buzz can be checked. These are individual tools; none becomes part of the speaker.`,['meter','signal','amplifier','microphone','power'],'The meter first touches the terminals. Then the signal source and amplifier drive the speaker while the measurement microphone listens. The powered devices require a power source.')
];
const sampleSteps={
 phone:[S('phone-1','fixture','Make a supporting body','A protective body gives the internal parts their positions.',()=>`Shape the phone’s enclosure and locating features with ${chip('mill')}. The body supports assemblies without becoming a tool.`,['mill']),S('phone-2','test','Add the electrical assemblies','Circuits and connectors bring the device’s systems together.',()=>`This sample starts with a ${chip('board')} and ${chip('case','enclosure + connectors')}. A ${chip('driver')} joins the assemblies to their supports.`,['driver']),S('phone-3','center','Fit the speaker','Place the sound-making part into the body and connect it.',()=>`Explore how the ${chip('speaker','Speaker',true)} is made, then return here. A ${chip('driver')} secures its mount; the board’s audio output connects to its terminals.`,['driver']),S('phone-4','test','Check the assembled phone','Verify the connected systems as one device.',()=>`A ${chip('power')} supplies the checking setup, and a ${chip('meter')} checks the electrical connections. Other phone systems are still to be detailed.`,['power','meter'])],
 coil:[S('coil-1','wire','Start with insulated wire','A conducting core, with neighboring turns electrically separated.',()=>`The coil starts with ${chip('wire','Insulated wire',true)}. Copper carries current; the thin ${chip('coating')} prevents adjacent turns from shorting.`),S('coil-2','wind','Guide the wire into a loop','A removable form defines the outline as the turns are placed.',()=>`The ${chip('fixture','Winding fixture',true)} supports the wire on its mandrel. Its guide lays successive turns into the intended shape. The form is a tool part, and is removed from the coil.`,['fixture'],'The fixture turns the form while the wire guide lays the turns. The form defines the outline and comes out afterward.'),S('coil-3','release','Release and check the coil','Keep the loop, leave flexible leads, and verify the electrical path.',()=>`Release the loop from the forming tool. Use a ${chip('meter')} to check continuity, then return to Speaker’s joining step. No production dimensions or winding specification is claimed here.`,['meter'],'The meter contacts the two free leads to check that the wire forms a continuous path.')],
 wire:[S('wire-1','wire','Form a conducting core','Bring the conductor to the required wire geometry.',()=>`A copper starting stock is shaped and drawn into wire. This diagram is a concept view; the upstream copper and drawing process are still to be specified.`),S('wire-2','coat','Add the insulating skin','Keep the winding’s neighboring turns electrically separate.',()=>`Apply the ${chip('coating')}, then check its continuity and condition. The coating is a part/input of the wire, rather than a third item category.`)],
 fixture:[S('fixture-1','fixture','Make the base and supports','A rigid base locates the rotating forming assembly.',()=>`Prepare the ${chip('base')} from ${chip('stock')}. Use a ${chip('drill')} for the support holes, then locate the ${chip('bearings')} and join them with ${chip('fasteners')}.`,['drill','driver']),S('fixture-2','wind','Shape the removable mandrel','Give the forming part the intended coil outline.',()=>`Make the ${chip('mandrel')} from suitable ${chip('stock')} using a ${chip('lathe')} or another shape-making setup. Its working outline follows the intended coil.`,['lathe']),S('fixture-3','guide','Fit the wire guide and check','The tool’s parts must locate consistently relative to the form.',()=>`Fit the ${chip('guide')} to the base using a ${chip('driver')}. Check the clearances with a ${chip('caliper')}. This page makes the fixture; its action on wire is shown in the caller’s step.`,['driver','caliper'])],
 alignment:[S('alignment-1','fixture','Shape a locating nest','A rigid nest gives the work a repeatable reference.',()=>`Make a ${chip('base')} with locating faces using a ${chip('mill')}. Its references follow the speaker frame and magnetic system.`,['mill']),S('alignment-2','center','Make the centering gauges','Thin removable references establish the coil’s position.',()=>`Shape the ${chip('gauges')} from ${chip('stock')} with an appropriate ${chip('lathe')} or finishing setup.`,['lathe']),S('alignment-3','release','Fit a release mechanism','Let the reference parts withdraw without moving the finished joint.',()=>`Fit supports and ${chip('fasteners')} with a ${chip('driver')}. Use a ${chip('caliper')} to check the reference geometry. The caller’s assembly step shows how the completed tool is used.`,['driver','caliper'])],
 magnet:[S('magnet-1','magnet','Choose the magnetic starting material','The intended field and geometry inform the material choice.',()=>`Start with a chosen ${chip('alloy')}. This stand-in does not prescribe a particular magnet chemistry.`),S('magnet-2','fixture','Form the body','Bring the starting material into the needed shape.',()=>`A ${chip('press')} may form the body, depending on the chosen material route.`,['press']),S('magnet-3','magnet','Consolidate and finish','Develop the body and finish its mating surfaces.',()=>`A material-dependent ${chip('furnace')} process may consolidate the body; a ${chip('grinder')} finishes its required surfaces.`,['furnace','grinder']),S('magnet-4','test','Magnetize and check','Give the finished body its intended magnetic state.',()=>`A ${chip('magnetizer')} applies the magnetizing field. Geometry and field checks follow; their specifications remain to be developed.`,['magnetizer'])],
 iron:[S('iron-1','magnet','Prepare the iron stock','Begin with material for the pole and return surfaces.',()=>`The input is ${chip('ironstock')}. These iron parts guide the magnet’s field; they are separate from the permanent magnet.`),S('iron-2','fixture','Shape the pole and return path','The geometry creates the narrow working air gap.',()=>`Use a ${chip('mill')} or ${chip('lathe')} to form the relevant surfaces.`,['mill','lathe']),S('iron-3','center','Finish the gap faces','The moving coil needs clear, controlled surfaces.',()=>`A ${chip('grinder')} finishes the working faces. This stand-in has no claimed dimensional tolerance.`,['grinder']),S('iron-4','test','Check the dimensions','Verify the geometry before assembling the magnetic system.',()=>`Use a ${chip('caliper')} and the appropriate gap references to check the finished parts.`,['caliper'])],
 meter:[S('meter-1','test','Make the measurement circuit','Known electrical values and circuitry form a measuring path.',()=>`Fit ${chip('resistors')} and measuring circuitry to a ${chip('board')} using a ${chip('solder')}.`,['solder']),S('meter-2','guide','Fit the display and leads','Connect the readable output and the contacts for the work.',()=>`Join a ${chip('display')} and ${chip('leads','test leads')} to the circuit, then fit the ${chip('case')}.`,['driver']),S('meter-3','test','Check against a reference','Confirm the completed tool against known values.',()=>`Use ${chip('resistors','reference resistors')} to check the reading. A powered measuring circuit also needs a ${chip('power')}. The speaker’s step shows how the finished meter is used.`,['power'])],
 signal:[S('signal-1','test','Make a waveform circuit','Create a controlled changing electrical signal.',()=>`Fit the waveform circuitry onto a ${chip('board')} with a ${chip('solder')}.`,['solder']),S('signal-2','guide','Fit controls and output','Provide a way to choose and connect the signal.',()=>`Fit the ${chip('case','enclosure, controls and connectors')} with a ${chip('driver')}.`,['driver']),S('signal-3','test','Power and verify the output','Check the completed source before using it in a test chain.',()=>`A ${chip('power')} runs the source. Appropriate waveform measurement verifies the output; that measurement setup is still to be detailed.`,['power'])],
 amplifier:[S('amplifier-1','test','Assemble the amplifier circuit','The circuit increases a signal’s ability to drive the load.',()=>`Fit the amplifier circuitry to a ${chip('board')} with a ${chip('solder')}.`,['solder']),S('amplifier-2','fixture','Fit support and connections','Provide protection, connectors and thermal management.',()=>`Fit the ${chip('case')} and circuit supports using a ${chip('driver')}. Heat-sinking choices depend on the actual design.`,['driver']),S('amplifier-3','test','Power and check the circuit','Verify the finished tool before connecting a speaker.',()=>`A ${chip('power')} runs the circuit. A ${chip('signal')} provides the input and a ${chip('meter')} checks the electrical connections.`,['power','signal','meter'])],
 microphone:[S('microphone-1','join','Fit a sound-sensing capsule','A sensing element turns acoustic pressure into a signal.',()=>`Fit the ${chip('capsule')} to a support and ${chip('case')}. The capsule’s own making route is a separate part page.`),S('microphone-2','test','Connect the measurement circuit','Bring the capsule output to the measuring setup.',()=>`Join the preamplifier ${chip('board')} and connectors with a ${chip('solder')}.`,['solder']),S('microphone-3','test','Check the completed microphone','A measurement tool needs a known response.',()=>`Check its response against an appropriate acoustic reference. The calibration setup is still to be detailed; the Speaker step shows where the completed tool listens.`)],
 power:[S('power-1','magnet','Make a fixed magnetic system','Prepare the field used by this generator example.',()=>`Assemble a ${chip('magnet')} and ${chip('iron')} on a ${chip('base')}, using an ${chip('clamp')}.`,['clamp']),S('power-2','wind','Fit the winding and shaft','Moving conductors in the field provide the generator action.',()=>`Form the ${chip('winding')} from ${chip('wire')} with a ${chip('fixture')}. Fit a ${chip('shaft')} and ${chip('bearings')}; a ${chip('lathe')} makes their supporting geometry. The ${chip('drive')} must supply mechanical energy. Magnets alone do not supply the power.`,['fixture','lathe','drive']),S('power-3','test','Condition the electrical output','Adapt the generated output to the intended load.',()=>`Connect an ${chip('conditioning')} on a ${chip('board')} with a ${chip('solder')}. This is a generator example, rather than a universal supply design.`,['solder']),S('power-4','test','Measure the output','Check the source while a real input drives it.',()=>`Use a ${chip('meter')} to check the output under an appropriate test load while the ${chip('drive')} turns the shaft. The source needs an energy input and operating limits.`,['meter','drive'])]
};
function genericSteps(id){const n=nodes[id];if(n.type==='Tool')return [S(id+'-1','fixture','Make the supporting parts','Prepare the structure and working parts of this tool.',()=>`Start with a ${chip('base')}, ${chip('stock')} and appropriate working parts. A ${chip(id==='drill'?'mill':'drill')} shapes or locates their mounting features. This example still needs a specific tool design.`,[id==='drill'?'mill':'drill']),S(id+'-2','guide','Assemble the mechanism','Join the supporting and working parts.',()=>`Fit ${chip('fasteners')} using a ${chip('driver')}. Electrical tools also require their circuit and a ${chip('power')}. These prerequisites are exposed rather than assumed.`,['driver']),S(id+'-3','test','Check the completed tool','Verify the tool’s working geometry and function.',()=>`Use a ${chip(id==='caliper'?'meter':'caliper')} and a suitable reference to check the tool. Its action on the work belongs in the caller’s step.`,[id==='caliper'?'meter':'caliper'])];return [S(id+'-1','wire','Prepare the input','Choose the material and geometry this part needs.',()=>`This page records the role of ${n.title.toLowerCase()} in its caller. Its material route and specification are still to be developed.`),S(id+'-2','fixture','Form and finish the part','Bring the input to its useful shape.',()=>`A relevant forming or finishing setup makes the part. ${chip('mill')} is shown as a sample fabrication tool where appropriate; the exact route is TBD.`,['mill']),S(id+'-3','test','Check the finished part','Confirm the features its caller depends on.',()=>`An appropriate ${chip('caliper')} or other reference checks the specified features before the part returns to the caller.`,['caliper'])]}
const parts={all:{title:'Four layers, one small system.',text:'Select a numbered layer to see its contribution.'},membrane:{title:'01 · Diaphragm + surround',text:'A thin film moves air; its flexible edge lets the center travel.'},coil:{title:'02 · Copper voice coil',text:'Changing current through the loop produces force in the magnetic gap.'},magnet:{title:'03 · Magnet + iron flux parts',text:'Separate parts: the magnet creates the field; the iron guides it across the gap.'},frame:{title:'04 · Frame + rear enclosure',text:'Separate structural and acoustic parts support the assembly.'}};
function toolGlyph(id){return `<svg viewBox="0 0 42 35" aria-hidden="true"><g fill="#f6f0db" stroke="#9b8750" stroke-width="1.3">${['meter','signal','amplifier','power'].includes(id)?'<rect x="7" y="4" width="27" height="27" rx="4"/><rect x="12" y="8" width="17" height="8" fill="#dce8d5"/><circle cx="20" cy="23" r="4"/><path d="M34 18h6v10" fill="none"/>':id==='microphone'?'<rect x="16" y="3" width="10" height="18" rx="5"/><path d="M11 14v6q0 9 10 9t10-9v-6M21 29v5m-8 0h16" fill="none"/>':'<path d="M5 27h32v5H5Z"/><path d="M10 27V10h7M32 27V10h-7" fill="none" stroke-width="3"/><rect x="12" y="12" width="18" height="10" rx="4" fill="#dce4d3"/>'}</g></svg>`}
function rack(tools){return tools.length?`<div class="tool-rack" aria-label="Tools beside this step">${tools.map(id=>`<button class="rack-tool" data-go="${id}" title="${nodes[id].title} · Tool · Open how it is made" aria-label="${nodes[id].title}. Tool. Open how it is made">${toolGlyph(id)}<span>${({'fixture':'Winder','alignment':'Aligner','microphone':'Microphone','signal':'Signal source','amplifier':'Amplifier','power':'Power source'})[id]||nodes[id].title}</span></button>`).join('')}</div>`:''}
function actionFigure(step){if(!step.use)return '';return `<div class="tool-action" aria-hidden="true">${toolGlyph(step.tools[0])}<span class="action-line"></span></div>`}
function stepsMarkup(steps,id){const ui=getUI(id);return steps.map((s,i)=>`<article class="step" data-step="${s.id}"><span class="step-number">${i+1}</span><figure class="step-visual">${stepDiagram(s.kind)}${actionFigure(s)}<figcaption class="diagram-caption">${s.kind==='test'?'check':s.kind==='center'?'alignment':s.kind==='join'?'moving assembly':s.kind==='wind'?'forming':'concept view'}</figcaption></figure><div class="step-content"><h3 class="step-title">${s.title}</h3><p class="step-summary">${s.summary}</p>${rack(s.tools)}<details id="${s.id}" ${ui.open.includes(s.id)?'open':''}><summary><span class="caret" aria-hidden="true"></span>How it comes together</summary><div class="step-detail">${s.detail()}</div>${s.use?`<div class="use-explanation"><button class="use-action" data-use="${s.id}" aria-pressed="false">▷ See the tool at work</button><p>${s.use}</p></div>`:''}</details></div></article>`).join('')}
function sourcesMarkup(){return `<details class="sources"><summary>About this illustration & sources</summary><p>Original, simplified technical illustrations, not to scale. Speaker physics: Klippel’s <a href="https://docs.klippel.de/db-lab/latest/simulation-auralisation/lsim/lsim.html" target="_blank" rel="noopener">Linear Simulation</a> and <a href="https://docs.klippel.de/db-lab/latest/transducer-parameter-identification/lsi3/lsi3.html" target="_blank" rel="noopener">Large Signal Identification</a> manuals. Stand-in pages illustrate the navigation and functional dependencies; they are conceptual outlines.</p></details>`}
function speakerMarkup(){const ui=getUI('speaker');return `<div class="card-topline"><span class="type">Part / 01</span><span class="meta">part of Phone</span></div><section class="hero"><div class="hero-copy"><span class="eyebrow">Electricity → movement → sound</span><h1>Speaker.</h1><p class="deck">A tiny moving system,<br>hiding in plain sight.</p><p class="intro">Follow how the parts come together, and what the tools do at each step.</p><div class="hero-tags"><span class="tag"><i class="tag-dot"></i>4 assembly steps</span><span class="tag">Conceptual micro-speaker</span></div></div><figure class="hero-art" id="speaker-art">${exploded(ui.selected)}<figcaption class="art-caption">Select a layer. Its individual parts appear in the steps below.</figcaption></figure></section><div class="legend" aria-label="Speaker layers">${[['all','All layers','#688c73'],['membrane','Film','#74b9b4'],['coil','Coil','#cc8851'],['magnet','Magnet + iron','#a29356'],['frame','Frame','#a9b8a6']].map(([k,t,c])=>`<button data-select="${k}" class="${ui.selected===k?'selected':''}" aria-pressed="${ui.selected===k}"><span class="swatch" style="background:${c}"></span>${t}</button>`).join('')}</div><div class="part-note" id="part-note"><strong>${parts[ui.selected].title}</strong><span>${parts[ui.selected].text}</span></div><section class="physics ${ui.motion?'motion-running':''}" aria-labelledby="physics-title"><div><span class="eyebrow">The idea in motion</span><h2 id="physics-title">What moves?<br>What stays still?</h2><p>Current changes direction. The coil moves in the fixed magnetic gap, taking the membrane with it. The magnet and iron stay still.</p><button class="play" data-motion aria-pressed="${ui.motion}">${ui.motion?'Ⅱ Pause the motion':'▷ Play the motion'}</button></div>${crossSection()}</section><button class="return-button" data-return>↑ Return to Phone</button><section class="making" aria-labelledby="making-title"><div class="section-heading"><h2 id="making-title">Put it together.</h2><span class="section-meta">4 STEPS · PARTS + TOOLS</span></div>${stepsMarkup(speakerSteps,'speaker')}</section><div class="bottom-note"><span class="badge">A concept, illustrated</span><p>The geometry is simplified. The coil must move freely; the finished speaker has thermal and mechanical limits.</p></div>${sourcesMarkup()}`}
function tbdArt(id){return `<svg viewBox="0 0 420 300" role="img" aria-label="TBD diagram for ${nodes[id].title}"><rect x="44" y="34" width="330" height="219" rx="20" fill="#f8f7ed" stroke="#c2c8af" stroke-dasharray="5 6"/><g transform="translate(82 70) scale(1.15)">${id==='phone'?'<rect x="53" y="-4" width="102" height="145" rx="17" fill="#e6ebda" stroke="#80917a" stroke-width="2"/><rect x="61" y="10" width="86" height="106" rx="7" fill="#fdfbf0" stroke="#bac6ad"/><path d="M88 0h32M91 127h26" stroke="#80917a" stroke-width="3"/><rect x="77" y="85" width="54" height="19" rx="6" fill="#bdd7c6" stroke="#759780"/><text x="104" y="78" text-anchor="middle" font-size="10" fill="#759780">speaker fits here</text>':nodes[id].type==='Tool'?'<rect x="48" y="16" width="120" height="93" rx="11" fill="#eae5cc" stroke="#aa995f" stroke-width="2"/><rect x="60" y="29" width="96" height="31" rx="4" fill="#e6edda" stroke="#aa995f"/><circle cx="109" cy="82" r="12" fill="#f8f4de" stroke="#aa995f"/><path d="M169 52h25v42" fill="none" stroke="#aa995f" stroke-width="3"/>':'<path d="m43 39 70-26 63 37-76 34Z" fill="#dde6d4" stroke="#91a188"/><path d="M43 39v56l57 33V84ZM100 84v44l76-25V50Z" fill="#c7d3bb" stroke="#91a188"/>'}</g><text x="210" y="276" font-size="12" text-anchor="middle" letter-spacing="1" fill="#8c977f">TBD DIAGRAM · FUNCTIONAL PLACEHOLDER</text></svg>`}
function sampleMarkup(id){const n=nodes[id],steps=sampleSteps[id]||genericSteps(id),copy={phone:['Parts → a complete phone','Many parts.<br>One useful object.','This regular Phone card holds the Speaker’s place in the device.'],coil:['Current → force','A loop of wire.<br>A moving part.','The coil moves with the membrane inside the speaker’s magnetic gap.'],fixture:['Make the tool','A form, a guide,<br>and a steady base.','Make the winding fixture from its own parts and fabrication tools. Its use on wire belongs in the caller’s step.'],alignment:['Make the tool','A reference nest.<br>A removable gauge.','Make the tool that locates the moving assembly during joining. Its use is shown in the caller’s assembly step.'],wire:['Part → another part','A conducting core.<br>An insulating skin.','The core carries current. Its coating keeps adjacent turns electrically separate.'],power:['Make the tool','An energy input.<br>An electrical output.','This generator example needs a mechanical drive. A magnetic field alone does not supply its energy.']}[id]||[n.type==='Tool'?'Make the tool':'Make the part',n.description+'.',n.type==='Tool'?`Explore ${n.title.toLowerCase()} as a tool with its own parts and fabrication tools.`:`Follow a conceptual making outline for ${n.title.toLowerCase()}.`];const art=['coil','fixture','wire'].includes(id)?sampleArt(id):tbdArt(id);return `<div class="card-topline"><span class="type ${n.type==='Tool'?'tool':''}">${n.type}</span><span class="meta">${relation(id)}</span></div><section class="hero"><div class="hero-copy"><span class="eyebrow">${copy[0]}</span><h1>${n.title}.</h1><p class="deck">${copy[1]}</p><p class="intro">${copy[2]}</p><span class="sample-label">This is a stand-in page</span></div><figure class="hero-art">${art}</figure></section>${path.length>1?`<button class="return-button" data-return>↑ Return to ${nodes[path.at(-2)].title}</button>`:''}<section class="making" aria-labelledby="making-title"><div class="section-heading"><h2 id="making-title">${n.type==='Tool'?'Make this tool.':'Put it together.'}</h2><span class="section-meta">${steps.length} SAMPLE STEPS</span></div>${stepsMarkup(steps,id)}</section><div class="bottom-note"><span class="badge">Concept outline</span><p>The sample shows this ${n.type.toLowerCase()}’s place in the chain. Its exact design, dimensions and production route are still to be developed.</p></div>${sourcesMarkup()}`}
function render(){const current=path.at(-1),n=nodes[current];document.title=`${n.title} · A phone, from the inside out`;trail.innerHTML=path.map((id,i)=>`${i?'<span class="trail-arrow" aria-hidden="true">/</span>':''}${i?`<span class="crumb-relation">${nodes[id].type==='Tool'?'uses tool':nodes[id].input?'input':'contains'}</span>`:''}<button class="crumb ${i===path.length-1?'current':''}" data-ancestor="${i}" ${i===path.length-1?'aria-current="page"':''}>${nodes[id].title}</button>`).join('');app.innerHTML=path.slice(0,-1).map((id,i)=>`<article class="ancestor" style="margin-left:${i*14}px">${compactHeader(id,i)}</article>`).join('')+`<div class="connection">${relation(current)}</div><article class="active-card level-${path.length-1} ${n.sample?'sample':''}" data-node="${current}" style="margin-left:${(path.length-1)*14}px"><div class="card-content">${current==='speaker'?speakerMarkup():sampleMarkup(current)}</div></article>`}
function selectLayer(part){getUI('speaker').selected=part;document.querySelector('#speaker-art').innerHTML=`${exploded(part)}<figcaption class="art-caption">Select a layer. Its individual parts appear in the steps below.</figcaption>`;document.querySelector('#part-note').innerHTML=`<strong>${parts[part].title}</strong><span>${parts[part].text}</span>`;document.querySelectorAll('.legend [data-select]').forEach(b=>{b.classList.toggle('selected',b.dataset.select===part);b.setAttribute('aria-pressed',b.dataset.select===part)});announce(parts[part].title+'. '+parts[part].text)}
document.addEventListener('click',event=>{const t=event.target.closest('[data-go],[data-ancestor],[data-return],[data-select],[data-motion],[data-use]');if(!t||navBusy)return;if(t.hasAttribute('data-go'))route(t.dataset.go,t);else if(t.hasAttribute('data-ancestor'))restore(Number(t.dataset.ancestor));else if(t.hasAttribute('data-return'))restore(path.length-2);else if(t.hasAttribute('data-select'))selectLayer(t.dataset.select);else if(t.hasAttribute('data-motion')){const ui=getUI('speaker');ui.motion=!ui.motion;document.querySelector('.physics').classList.toggle('motion-running',ui.motion);t.setAttribute('aria-pressed',ui.motion);t.textContent=ui.motion?'Ⅱ Pause the motion':'▷ Play the motion';}else if(t.hasAttribute('data-use')){const step=t.closest('.step'),active=step.classList.toggle('using-tool');t.setAttribute('aria-pressed',active);t.textContent=active?'Ⅱ Pause the tool action':'▷ See the tool at work';announce(active?step.querySelector('.use-explanation p').textContent:'Tool action paused.')}});
document.addEventListener('keydown',event=>{const t=event.target.closest('svg [role="button"]');if(t&&(event.key==='Enter'||event.key===' ')){event.preventDefault();selectLayer(t.dataset.select)}});
app.addEventListener('toggle',event=>{if(event.target.matches('.step details'))getUI(path.at(-1)).open=[...app.querySelectorAll('.step details[open]')].map(d=>d.id)},true);
getUI('phone').open=['phone-3'];getUI('coil').open=['coil-1','coil-2'];getUI('wire').open=['wire-1'];getUI('fixture').open=['fixture-1','fixture-2'];getUI('alignment').open=['alignment-1'];
render();
